public class CategoryPlot_removeRangeMarker_TriageGen2Test {

    private CategoryPlot plot;
    private Marker mockMarker;
    private CategoryDataset mockDataset;
    private CategoryAxis mockDomainAxis;
    private ValueAxis mockRangeAxis;

    @Before
    public void setUp() {
        mockDataset = mock(CategoryDataset.class);
        mockDomainAxis = mock(CategoryAxis.class);
        mockRangeAxis = mock(ValueAxis.class);
        mockMarker = mock(Marker.class);
        plot = new CategoryPlot(mockDataset, mockDomainAxis, mockRangeAxis, null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRemoveRangeMarker_NullMarker_ThrowsException() {
        plot.removeRangeMarker(0, null, Layer.FOREGROUND, true);
    }

    @Test
    public void testRemoveRangeMarker_MarkersListNull_ReturnsTrue() throws Exception {
        // Force markers map to be empty/null for specific index
        setMarkersMap(Layer.FOREGROUND, new HashMap<>());

        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.FOREGROUND, true);
        assertTrue("Should return true if markers list for index is null", result);
    }

    @Test
    public void testRemoveRangeMarker_Foreground_MarkerExists_Removed_NotifyTrue() throws Exception {
        Map<Integer, ArrayList> foregroundMap = new HashMap<>();
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);
        foregroundMap.put(0, list);
        setMarkersMap(Layer.FOREGROUND, foregroundMap);

        // We can't easily verify fireChangeEvent() unless we spy or use a subclass, 
        // but we can verify the return value and state.
        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Should return true when marker is removed", result);
        assertEquals("List should be empty", 0, list.size());
    }

    @Test
    public void testRemoveRangeMarker_Foreground_MarkerExists_Removed_NotifyFalse() throws Exception {
        Map<Integer, ArrayList> foregroundMap = new HashMap<>();
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);
        foregroundMap.put(0, list);
        setMarkersMap(Layer.FOREGROUND, foregroundMap);

        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.FOREGROUND, false);

        assertTrue("Should return true when marker is removed", result);
        assertEquals(0, list.size());
    }

    @Test
    public void testRemoveRangeMarker_Foreground_MarkerDoesNotExist_ReturnsFalse() throws Exception {
        Map<Integer, ArrayList> foregroundMap = new HashMap<>();
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mock(Marker.class)); // Different marker
        foregroundMap.put(0, list);
        setMarkersMap(Layer.FOREGROUND, foregroundMap);

        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.FOREGROUND, true);

        assertFalse("Should return false when marker is not found", result);
        assertEquals(1, list.size());
    }

    @Test
    public void testRemoveRangeMarker_Background_MarkerExists_Removed_NotifyTrue() throws Exception {
        Map<Integer, ArrayList> backgroundMap = new HashMap<>();
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);
        backgroundMap.put(5, list);
        setMarkersMap(Layer.BACKGROUND, backgroundMap);

        boolean result = plot.removeRangeMarker(5, mockMarker, Layer.BACKGROUND, true);

        assertTrue("Should return true for background removal", result);
        assertEquals(0, list.size());
    }

    @Test
    public void testRemoveRangeMarker_Background_MarkerExists_Removed_NotifyFalse() throws Exception {
        Map<Integer, ArrayList> backgroundMap = new HashMap<>();
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);
        backgroundMap.put(5, list);
        setMarkersMap(Layer.BACKGROUND, backgroundMap);

        boolean result = plot.removeRangeMarker(5, mockMarker, Layer.BACKGROUND, false);

        assertTrue("Should return true for background removal", result);
        assertEquals(0, list.size());
    }

    @Test
    public void testRemoveRangeMarker_Background_MarkerDoesNotExist_ReturnsFalse() throws Exception {
        Map<Integer, ArrayList> backgroundMap = new HashMap<>();
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mock(Marker.class));
        backgroundMap.put(5, list);
        setMarkersMap(Layer.BACKGROUND, backgroundMap);

        boolean result = plot.removeRangeMarker(5, mockMarker, Layer.BACKGROUND, true);

        assertFalse("Should return false for background non-existent marker", result);
        assertEquals(1, list.size());
    }

    @Test
    public void testRemoveRangeMarker_Background_MarkersListNull_ReturnsTrue() throws Exception {
        setMarkersMap(Layer.BACKGROUND, new HashMap<>());

        boolean result = plot.removeRangeMarker(10, mockMarker, Layer.BACKGROUND, true);
        assertTrue("Should return true if background markers list is null", result);
    }

    /**
     * Helper to inject the private maps via reflection to simulate the state of CategoryPlot.
     */
    @SuppressWarnings("unchecked")
    private void setMarkersMap(Layer layer, Map<Integer, ArrayList> map) throws Exception {
        String fieldName = (layer == Layer.FOREGROUND) ? "foregroundRangeMarkers" : "backgroundRangeMarkers";
        Field field = CategoryPlot.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(plot, map);
    }
}
